package io.github.care_agent.app.runtime

import android.content.Context
import org.json.JSONObject

data class RuntimeArchive(
    val asset: String,
    val bytes: Long,
    val sha256: String?,
    val uncompressedBytes: Long,
)

/**
 * Describes the offline ARM64 Linux/Node/DSH/care-bot runtime bundled in this APK
 * (`assets/runtime/manifest.json`, generated by `runtime/build-runtime.sh`).
 */
data class RuntimeManifest(
    val runtimeVersion: String,
    val abi: String,
    val archives: List<RuntimeArchive>,
    val dshVersion: String,
    val nodeVersion: String,
    val launchArgv: List<String>,
    val launchEnv: Map<String, String>,
    val raw: JSONObject,
) {
    companion object {
        const val ASSET_DIR = "runtime"
        const val MANIFEST_PATH = "$ASSET_DIR/manifest.json"

        fun loadOrNull(context: Context): RuntimeManifest? = runCatching {
            val text = context.assets.open(MANIFEST_PATH).bufferedReader().use { it.readText() }
            fromJson(JSONObject(text))
        }.getOrNull()

        fun fromJson(json: JSONObject): RuntimeManifest {
            val schema = if (json.has("schema")) json.getInt("schema") else 1
            val archives = when (schema) {
                1 -> listOf(
                    RuntimeArchive(
                        asset = json.getString("rootfs"),
                        bytes = json.optLong("rootfsBytes", -1L),
                        sha256 = json.optString("rootfsSha256").ifEmpty { null },
                        uncompressedBytes = json.optLong("uncompressedBytes", -1L),
                    ),
                )
                2 -> {
                    val layers = json.getJSONObject("layers")
                    listOf("base", "engine").map { name ->
                        val layer = layers.getJSONObject(name)
                        RuntimeArchive(
                            asset = layer.getString("asset"),
                            bytes = layer.getLong("bytes"),
                            sha256 = layer.optString("sha256").ifEmpty { null },
                            uncompressedBytes = layer.optLong("uncompressedBytes", -1L),
                        )
                    }
                }
                else -> error("Unsupported runtime manifest schema: $schema")
            }
            val launch = json.optJSONObject("launch") ?: JSONObject()
            val argvJson = launch.optJSONArray("argv")
            val argv = if (argvJson != null) List(argvJson.length()) { argvJson.getString(it) } else emptyList()
            val envJson = launch.optJSONObject("env") ?: JSONObject()
            val env = envJson.keys().asSequence().associateWith { envJson.getString(it) }
            return RuntimeManifest(
                runtimeVersion = json.getString("runtimeVersion"),
                abi = json.optString("abi", "arm64-v8a"),
                archives = archives,
                dshVersion = json.optString("dshVersion"),
                nodeVersion = json.optString("nodeVersion"),
                launchArgv = argv,
                launchEnv = env,
                raw = json,
            )
        }
    }
}
